package gin

import (
	"errors"
	"fmt"
	"testing"
)

type probeErr string

func (e probeErr) Error() string { return string(e) }

func TestZZProbeUnwrap(t *testing.T) {
	inner := probeErr("some error")
	// pointer
	t.Log("ptr Is:", errors.Is(&Error{Err: inner, Type: ErrorTypeAny}, inner))
	t.Log("ptr Unwrap:", errors.Unwrap(&Error{Err: inner}) == error(inner))
	// value
	t.Log("val Is:", errors.Is(Error{Err: inner, Type: ErrorTypeAny}, inner))
	var v error = Error{Err: inner, Type: ErrorTypeAny}
	t.Log("val as error, Is:", errors.Is(v, inner))
	t.Log("val wrapped in fmt:", errors.Is(fmt.Errorf("w: %w", Error{Err: inner}), inner))
	// errors.As
	var pe probeErr
	t.Log("ptr As:", errors.As(fmt.Errorf("w: %w", &Error{Err: inner}), &pe))
	var pe2 probeErr
	t.Log("val As:", errors.As(fmt.Errorf("w: %w", Error{Err: inner}), &pe2))
}
EOF
cp /tmp/zz_probe_test.go /gin/zz_probe_test.go && go test -run TestZZProbeUnwrap -v . 2>&1 | head -30; rm -f /gin/zz_probe_test.go

